/**
 * Framework sync support used by this fork.
 *
 * The upstream manifest is the source of truth for component selection. This
 * module only provides the derived-file metadata and CSS index renderer needed
 * by the fork's sync and verify commands.
 */

export const DERIVED_FILES = ["app/css/framework.css"];

/**
 * @param {string[]} cssBasenames
 */
export function renderFrameworkCssIndex(cssBasenames = []) {
  const lines = [
    "/**",
    " * Framework CSS index — lists shared partials under this directory.",
    " * Regenerated by framework sync/verify from the selected component set;",
    " * do not treat hand edits as durable in forks.",
    " */",
    ...cssBasenames.map((name) => `@import url("${name}");`),
    "",
  ];
  return lines.join("\n");
}
